       instruction_en = 'Twenty-four names, each naming a limb, from the feet upward to the head, and a twenty-fourth for the whole body. Offer a flower or a pinch of akshatai at each.',
       source_ref     = 'Sampradaya Vratha Pooja Vidhi (Giri), pp.115-137, pp.121-123',
       updated_at     = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Anga Pooja';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham';
  if n <> 31 then raise exception 'varalakshmi has % steps, expected 31', n; end if;

  -- The numbering is 1..31 with no gaps and nothing left parked.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and (step_number < 1 or step_number > 31);
  if n > 0 then raise exception '% steps are outside 1..31', n; end if;
  select count(distinct step_number) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham';
  if n <> 31 then raise exception 'step numbers are not distinct'; end if;

  -- The three new/split steps are in the book-s order.
  select step_number into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam';
  if n <> 10 then raise exception 'Dhyanam is at % , expected 10', n; end if;
  select step_number into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dora Sthapanam';
  if n <> 11 then raise exception 'Dora Sthapanam is at %, expected 11', n; end if;
  select step_number into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Avahanam';
  if n <> 12 then raise exception 'Avahanam is at %, expected 12', n; end if;

  -- The anga pooja is the book-s twenty-four, numbered 1..24.
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja';
  if n <> 24 then raise exception 'anga pooja has % rows, expected 24', n; end if;

  -- Distinctive phrases of the book, one per replaced step, so that a silent
  -- no-op cannot pass for a conversion.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam'
     and mantra_sanskrit like '%समुद्रराज%';
  if n <> 1 then raise exception 'Dhyanam does not carry the book reading'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vastram, Abharanam & Mangalyam'
     and mantra_sanskrit like '%माङ्गल्यमणि%';
  if n <> 1 then raise exception 'Vastram, Abharanam & Mangalyam does not carry the book reading'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam'
     and mantra_sanskrit like '%नवतन्तु%';
  if n <> 1 then raise exception 'Sharadu Dharanam does not carry the book reading'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
     and mantra_sanskrit like '%हिरण्यगर्भ%';
  if n <> 1 then raise exception 'Vayana Dhanam does not carry the book reading'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Udvasanam'
     and mantra_sanskrit like '%कुंभात्%';
  if n <> 1 then raise exception 'Udvasanam does not carry the book reading'; end if;

  -- Every step with Devanagari still has the other two scripts.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham'
     and coalesce(trim(mantra_sanskrit), '') <> ''
     and (mantra_tamil is null or mantra_translit is null);
  if n > 0 then raise exception '% steps are missing a script', n; end if;

  -- And no title got clobbered by a mantra, which is what 0025 did.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham'
     and (length(coalesce(step_title_en, '')) > 60
       or length(coalesce(step_title_ta, '')) > 60
       or step_title_ta like '%।%');
  if n > 0 then raise exception '% titles look like mantra text', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
